#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <stdatomic.h>

#define MAX_SESSIONS 1024
#define SESSION_ID_LEN 32
#define MAX_DATA_LEN 4096

typedef struct session {
    char id[SESSION_ID_LEN + 1];
    char *data;
    size_t data_len;
    atomic_int refcount;
    atomic_int state;  /* 0=free, 1=active, 2=closing */
    pthread_mutex_t lock;
} session_t;

typedef struct session_store {
    session_t sessions[MAX_SESSIONS];
    pthread_rwlock_t global_lock;
} session_store_t;

static session_store_t g_store;

void init_store(void) {
    pthread_rwlock_init(&g_store.global_lock, NULL);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        atomic_store(&g_store.sessions[i].state, 0);
        atomic_store(&g_store.sessions[i].refcount, 0);
        pthread_mutex_init(&g_store.sessions[i].lock, NULL);
        g_store.sessions[i].data = NULL;
    }
}

/* Find session by ID, increment refcount to prevent freeing */
static session_t *session_acquire(const char *id) {
    pthread_rwlock_rdlock(&g_store.global_lock);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        session_t *s = &g_store.sessions[i];
        if (atomic_load(&s->state) == 1) {
            if (strncmp(s->id, id, SESSION_ID_LEN) == 0) {
                /* Increment refcount to hold reference */
                atomic_fetch_add(&s->refcount, 1);
                pthread_rwlock_unlock(&g_store.global_lock);
                return s;
            }
        }
    }
    pthread_rwlock_unlock(&g_store.global_lock);
    return NULL;
}

/* Release reference to session */
static void session_release(session_t *s) {
    int prev = atomic_fetch_sub(&s->refcount, 1);
    if (prev == 1 && atomic_load(&s->state) == 2) {
        /* Last reference and session is closing - free data */
        pthread_mutex_lock(&s->lock);
        if (s->data) {
            memset(s->data, 0, s->data_len);
            free(s->data);
            s->data = NULL;
            s->data_len = 0;
        }
        atomic_store(&s->state, 0);
        pthread_mutex_unlock(&s->lock);
    }
}

/* Create a new session */
int session_create(const char *id, const char *initial_data, size_t data_len) {
    if (!id || strlen(id) > SESSION_ID_LEN || !initial_data || data_len > MAX_DATA_LEN)
        return -1;

    pthread_rwlock_wrlock(&g_store.global_lock);

    /* Check for duplicate */
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (atomic_load(&g_store.sessions[i].state) == 1 &&
            strncmp(g_store.sessions[i].id, id, SESSION_ID_LEN) == 0) {
            pthread_rwlock_unlock(&g_store.global_lock);
            return -2;
        }
    }

    /* Find free slot */
    for (int i = 0; i < MAX_SESSIONS; i++) {
        session_t *s = &g_store.sessions[i];
        if (atomic_load(&s->state) == 0) {
            strncpy(s->id, id, SESSION_ID_LEN);
            s->id[SESSION_ID_LEN] = '\0';
            s->data = malloc(data_len + 1);
            if (!s->data) {
                pthread_rwlock_unlock(&g_store.global_lock);
                return -3;
            }
            memcpy(s->data, initial_data, data_len);
            s->data[data_len] = '\0';
            s->data_len = data_len;
            atomic_store(&s->refcount, 0);
            atomic_store(&s->state, 1);
            pthread_rwlock_unlock(&g_store.global_lock);
            return 0;
        }
    }
    pthread_rwlock_unlock(&g_store.global_lock);
    return -4;
}

/* Read session data - returns copy */
int session_read(const char *id, char *buf, size_t buf_len, size_t *out_len) {
    if (!id || !buf || !out_len) return -1;

    session_t *s = session_acquire(id);
    if (!s) return -2;

    pthread_mutex_lock(&s->lock);
    if (s->data && s->data_len <= buf_len) {
        memcpy(buf, s->data, s->data_len);
        *out_len = s->data_len;
        pthread_mutex_unlock(&s->lock);
        session_release(s);
        return 0;
    }
    pthread_mutex_unlock(&s->lock);
    session_release(s);
    return -3;
}

/* Update session data */
int session_update(const char *id, const char *new_data, size_t data_len) {
    if (!id || !new_data || data_len > MAX_DATA_LEN) return -1;

    session_t *s = session_acquire(id);
    if (!s) return -2;

    pthread_mutex_lock(&s->lock);
    /* Check state again under lock */
    if (atomic_load(&s->state) != 1) {
        pthread_mutex_unlock(&s->lock);
        session_release(s);
        return -3;
    }

    char *new_buf = malloc(data_len + 1);
    if (!new_buf) {
        pthread_mutex_unlock(&s->lock);
        session_release(s);
        return -4;
    }
    memcpy(new_buf, new_data, data_len);
    new_buf[data_len] = '\0';

    if (s->data) {
        memset(s->data, 0, s->data_len);
        free(s->data);
    }
    s->data = new_buf;
    s->data_len = data_len;

    pthread_mutex_unlock(&s->lock);
    session_release(s);
    return 0;
}

/* Destroy session */
int session_destroy(const char *id) {
    if (!id) return -1;

    session_t *s = session_acquire(id);
    if (!s) return -2;

    /* Mark as closing - this is the critical section */
    atomic_store(&s->state, 2);

    /* Release our reference - if refcount drops to 0, cleanup happens */
    session_release(s);
    return 0;
}

/* Periodic cleanup - called by maintenance thread */
void session_gc(void) {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        session_t *s = &g_store.sessions[i];
        if (atomic_load(&s->state) == 2 && atomic_load(&s->refcount) == 0) {
            pthread_mutex_lock(&s->lock);
            /* Double-check under lock */
            if (atomic_load(&s->state) == 2 && atomic_load(&s->refcount) == 0) {
                if (s->data) {
                    memset(s->data, 0, s->data_len);
                    free(s->data);
                    s->data = NULL;
                    s->data_len = 0;
                }
                atomic_store(&s->state, 0);
            }
            pthread_mutex_unlock(&s->lock);
        }
    }
}

/* HTTP request handler simulation */
void *handle_request(void *arg) {
    char *request = (char *)arg;
    char cmd[16], session_id[SESSION_ID_LEN + 1], data[MAX_DATA_LEN + 1];
    size_t data_len;

    if (sscanf(request, "%15s %32s", cmd, session_id) < 2) {
        free(request);
        return NULL;
    }

    if (strcmp(cmd, "READ") == 0) {
        char buf[MAX_DATA_LEN + 1];
        size_t out_len;
        if (session_read(session_id, buf, sizeof(buf), &out_len) == 0) {
            /* Process read data */
            buf[out_len] = '\0';
        }
    } else if (strcmp(cmd, "UPDATE") == 0) {
        char *space = strchr(request + strlen(cmd) + 1 + strlen(session_id) + 1, ' ');
        if (space) {
            data_len = strlen(space + 1);
            if (data_len <= MAX_DATA_LEN) {
                session_update(session_id, space + 1, data_len);
            }
        }
    } else if (strcmp(cmd, "DELETE") == 0) {
        session_destroy(session_id);
    }

    free(request);
    return NULL;
}

/* GC thread */
void *gc_thread(void *arg) {
    (void)arg;
    while (1) {
        sleep(1);
        session_gc();
    }
    return NULL;
}

int main(void) {
    init_store();

    pthread_t gc;
    pthread_create(&gc, NULL, gc_thread, NULL);

    /* Simulate incoming requests */
    session_create("user-session-abc123", "initial_token=xyz", 17);

    /* Simulate concurrent access */
    char *req1 = strdup("READ user-session-abc123");
    char *req2 = strdup("DELETE user-session-abc123");
    char *req3 = strdup("READ user-session-abc123");

    pthread_t t1, t2, t3;
    pthread_create(&t1, NULL, handle_request, req1);
    pthread_create(&t2, NULL, handle_request, req2);
    pthread_create(&t3, NULL, handle_request, req3);

    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    pthread_join(t3, NULL);

    return 0;
}
